// NewCreateResponseBody builds the HTTP response body from the result of the
// "create" endpoint of the "user" service.
func NewCreateResponseBody(res *userviews.UserView) *CreateResponseBody {
	body := &CreateResponseBody{
		ID:          *res.ID,
		Email:       *res.Email,
		Username:    res.Username,
		FirstName:   *res.FirstName,
		LastName:    *res.LastName,
		DisplayName: res.DisplayName,
		Status:      string(*res.Status),
		UserType:    string(*res.UserType),
		Phone:       res.Phone,
		LastLoginAt: res.LastLoginAt,
		CreatedAt:   *res.CreatedAt,
		UpdatedAt:   *res.UpdatedAt,
	}
	if res.PersonType != nil {
		personType := string(*res.PersonType)
		body.PersonType = &personType
	}
	if res.EmploymentStatus != nil {
		employmentStatus := string(*res.EmploymentStatus)
		body.EmploymentStatus = &employmentStatus
	}
	if res.Profile != nil {
		body.Profile = marshalUserviewsUserProfileViewToUserProfileResponseBody(res.Profile)
	}
	if res.Preferences != nil {
		body.Preferences = marshalUserviewsUserPreferencesViewToUserPreferencesResponseBody(res.Preferences)
	}
	return body
}

