// NewCreateUserPayload builds a user service create endpoint payload.
func NewCreateUserPayload(body *CreateRequestBody) *user.CreateUserPayload {
	v := &user.CreateUserPayload{
		Email:     *body.Email,
		Username:  body.Username,
		FirstName: *body.FirstName,
		LastName:  *body.LastName,
		Password:  body.Password,
		UserType:  user.UserType(*body.UserType),
		Phone:     body.Phone,
	}
	if body.PersonType != nil {
		personType := user.PersonType(*body.PersonType)
		v.PersonType = &personType
	}
	if body.EmploymentStatus != nil {
		employmentStatus := user.EmploymentStatus(*body.EmploymentStatus)
		v.EmploymentStatus = &employmentStatus
	}
	if body.SendInvitation != nil {
		v.SendInvitation = *body.SendInvitation
	}
	if body.Profile != nil {
		v.Profile = unmarshalUserProfileRequestBodyToUserUserProfile(body.Profile)
	}
	if body.Preferences != nil {
		v.Preferences = unmarshalUserPreferencesRequestBodyToUserUserPreferences(body.Preferences)
	}
	if body.SendInvitation == nil {
		v.SendInvitation = true
	}

	return v
}

